				h_addi_spec_rs1_addr_known: assert(no_x5(chk.spec_rs1_addr));
				h_addi_spec_rs2_addr_known: assert(no_x5(chk.spec_rs2_addr));
				h_addi_spec_rd_addr_known: assert(no_x5(chk.spec_rd_addr));
				h_addi_spec_rs1_addr_matches_insn: assert(chk.spec_rs1_addr == rvfi_insn[19:15]);
				h_addi_spec_rs2_addr_is_zero: assert(chk.spec_rs2_addr == 5'd0);
				h_addi_spec_rd_addr_matches_insn: assert(chk.spec_rd_addr == rvfi_insn[11:7]);

